package com.alpharip.staffmod.RecordingStudio.ui;
import com.alpharip.staffmod.RecordingStudio.camera.*;import net.minecraft.client.gui.*;import java.io.File;import java.io.IOException;
/** In-game camera positioning and path editor for the standalone Recording Studio. */
public final class CameraEditorScreen extends GuiScreen {
 private final GuiScreen parent;private final CameraController camera;private final CameraPathStore store;private CameraPath path=new CameraPath("Recording Studio Camera Path");private GuiTextField pathId;private String status="Camera marker is shown in the world while active.";
 public CameraEditorScreen(GuiScreen parent,CameraController camera,File dataDirectory){if(parent==null||camera==null||dataDirectory==null)throw new IllegalArgumentException();this.parent=parent;this.camera=camera;store=new FileCameraPathStore(new File(dataDirectory,"recordingstudio/camera-paths"));}
 public boolean doesGuiPauseGame(){return false;}
 public void initGui(){String old=pathId==null?"studio-camera":pathId.getText();buttonList.clear();int x=width/2-150,y=height/2-82;buttonList.add(new AlphaStudioButton(0,x,y,90,20,"X -"));buttonList.add(new AlphaStudioButton(1,x+95,y,90,20,"X +"));buttonList.add(new AlphaStudioButton(2,x+190,y,110,20,"Activate"));buttonList.add(new AlphaStudioButton(3,x,y+24,90,20,"Y -"));buttonList.add(new AlphaStudioButton(4,x+95,y+24,90,20,"Y +"));buttonList.add(new AlphaStudioButton(5,x+190,y+24,110,20,"Deactivate"));buttonList.add(new AlphaStudioButton(6,x,y+48,90,20,"Z -"));buttonList.add(new AlphaStudioButton(7,x+95,y+48,90,20,"Z +"));buttonList.add(new AlphaStudioButton(8,x+190,y+48,110,20,"FOV +"));buttonList.add(new AlphaStudioButton(9,x,y+72,90,20,"Yaw -"));buttonList.add(new AlphaStudioButton(10,x+95,y+72,90,20,"Yaw +"));buttonList.add(new AlphaStudioButton(11,x+190,y+72,110,20,"Pitch +"));buttonList.add(new AlphaStudioButton(12,x,y+102,90,20,"Add Point"));buttonList.add(new AlphaStudioButton(13,x+95,y+102,90,20,"Play Path"));buttonList.add(new AlphaStudioButton(14,x+190,y+102,110,20,"Stop Path"));buttonList.add(new AlphaStudioButton(15,width/2-50,y+132,100,20,"Back"));pathId=new GuiTextField(16,fontRendererObj,width/2-150,y+162,145,20);pathId.setMaxStringLength(80);pathId.setText(old);buttonList.add(new AlphaStudioButton(16,width/2+5,y+162,70,20,"Save"));buttonList.add(new AlphaStudioButton(17,width/2+80,y+162,70,20,"Load"));}
 private void adjust(double x,double y,double z,float yaw,float pitch,float fov){CameraPose p=camera.getPose();try{camera.setPose(new CameraPose(p.x+x,p.y+y,p.z+z,p.yaw+yaw,p.pitch+pitch,p.roll,Math.max(1,Math.min(179,p.fov+fov))));status="Camera position updated";}catch(Exception e){status="Camera update failed: "+e.getMessage();}}
 protected void actionPerformed(GuiButton b){if(b.id==0)adjust(-1,0,0,0,0,0);else if(b.id==1)adjust(1,0,0,0,0,0);else if(b.id==2){try{camera.activate();status="Camera active — yellow marker shows its world position";}catch(Exception e){status="Camera activation failed: "+e.getMessage();}}else if(b.id==3)adjust(0,-1,0,0,0,0);else if(b.id==4)adjust(0,1,0,0,0,0);else if(b.id==5){try{camera.deactivate();status="Camera deactivated";}catch(Exception e){status="Camera shutdown failed: "+e.getMessage();}}else if(b.id==6)adjust(0,0,-1,0,0,0);else if(b.id==7)adjust(0,0,1,0,0,0);else if(b.id==8)adjust(0,0,0,0,0,5);else if(b.id==9)adjust(0,0,0,-15,0,0);else if(b.id==10)adjust(0,0,0,15,0,0);else if(b.id==11)adjust(0,0,0,0,10,0);else if(b.id==12){path.add(new CameraWaypoint("point-"+java.util.UUID.randomUUID(),camera.getPose(),2000,500,"SMOOTH"));status="Waypoint added: "+path.getWaypoints().size();}else if(b.id==13){try{if(path.getWaypoints().size()<2)throw new IllegalStateException("Add at least two waypoints first");camera.activate();camera.playPath(path,System.currentTimeMillis());status="Camera path playing";}catch(Exception e){status="Could not play path: "+e.getMessage();}}else if(b.id==14){camera.stopPath();status="Camera path stopped";}else if(b.id==15)mc.displayGuiScreen(parent);else if(b.id==16)save();else if(b.id==17)load();}
 private void save(){try{store.save(pathId.getText().trim(),path);status="Camera path saved";}catch(Exception e){status="Save failed: "+e.getMessage();}}
 private void load(){try{path=store.load(pathId.getText().trim());camera.stopPath();status="Camera path loaded ("+path.getWaypoints().size()+" points)";}catch(Exception e){status="Load failed: "+e.getMessage();}}
 protected void keyTyped(char c,int k)throws IOException{if(k==1){mc.displayGuiScreen(parent);return;}if(pathId!=null)pathId.textboxKeyTyped(c,k);super.keyTyped(c,k);}
 protected void mouseClicked(int x,int y,int b)throws IOException{super.mouseClicked(x,y,b);if(pathId!=null)pathId.mouseClicked(x,y,b);}
 public void drawScreen(int mx,int my,float pt){drawDefaultBackground();Gui.drawRect(width/2-165,10,width/2+165,height-8,0xE8101010);Gui.drawRect(width/2-165,10,width/2+165,12,0xFFFFC83D);drawCenteredString(fontRendererObj,"ALPHA CLIENT  /  RECORDING STUDIO",width/2,20,0xFFAAAAAA);drawCenteredString(fontRendererObj,"CAMERA EDITOR",width/2,34,0xFFFFC83D);CameraPose p=camera.getPose();drawCenteredString(fontRendererObj,String.format(java.util.Locale.ROOT,"X %.2f  Y %.2f  Z %.2f",p.x,p.y,p.z),width/2,42,0xFFFFFF);drawCenteredString(fontRendererObj,String.format(java.util.Locale.ROOT,"Yaw %.1f  Pitch %.1f  FOV %.1f",p.yaw,p.pitch,p.fov),width/2,56,0xFFFFFF);drawString(fontRendererObj,"Path ID",width/2-150,height/2+82,0xBBBBBB);if(pathId!=null)pathId.drawTextBox();drawCenteredString(fontRendererObj,"Waypoints: "+path.getWaypoints().size()+" | "+path.getName(),width/2,height/2+198,0xFFFFFF);drawCenteredString(fontRendererObj,status,width/2,height-12,0xBBBBBB);super.drawScreen(mx,my,pt);}
}
